// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using System.Threading;
using Campground.Shared.Registry;
using MediaBrowser.Controller.Library;
using MediaBrowser.Controller.Session;

namespace Campground.Shared.Contracts
{
    /// <summary>One Jellyfin session that is playing something, as the quiet check sees it.</summary>
    /// <param name="UserName">Who is playing, for the status line. Null when Jellyfin doesn't know.</param>
    /// <param name="DeviceName">Where, for the status line.</param>
    /// <param name="Paused">Paused playback still holds quiet: it resumes without a new <c>PlaybackStart</c>.</param>
    internal sealed record PlayingSession(string? UserName, string? DeviceName, bool Paused);

    /// <summary>The answer to "is the server quiet?".</summary>
    /// <param name="Quiet">True when nothing holds it and nothing has played for the time asked.</param>
    /// <param name="QuietFor">How long nothing has played and nothing has held it. Zero while something holds it.</param>
    /// <param name="Holding">One plain line per thing holding it, for a status page ("Alice is playing on Living room
    /// TV"). It names users and devices, so show it to admins only and never log it.</param>
    internal sealed record QuietState(bool Quiet, TimeSpan QuietFor, IReadOnlyList<string> Holding);

    /// <summary>
    /// Issue #31 item 4 (#20 M4): one answer to "may I do something heavy or disruptive now?", for FieldGuide's
    /// rebuilds, Trailhead's certificate restart and GameTent's tent-image updates.
    /// <para>
    /// Quiet means all of these:
    /// </para>
    /// <list type="bullet">
    /// <item>no Jellyfin session is playing, <b>paused included</b>;</item>
    /// <item>no playback has been seen for the time asked, counted from the last <c>PlaybackStart</c>,
    /// <c>PlaybackProgress</c> or <c>PlaybackStopped</c> (ffmpeg keeps writing for a few seconds after the last
    /// report, and the next episode usually starts at once);</item>
    /// <item>no live <see cref="Sessions"/> activity with a user (a GameTent stream isn't Jellyfin playback), or of
    /// a kind the caller names. Activities with no user, such as downloads and rebuilds, don't hold it by
    /// default;</item>
    /// <item>no live hardware-encoder lease (a transcode can outlive its session).</item>
    /// </list>
    /// <para>
    /// Quiet time also restarts when a holder goes away: at every check that finds one, and when an activity with a
    /// user ends (GameTent, #51). Callers poll while they wait, so a lease that ends between polls counts from the
    /// last poll that saw it.
    /// </para>
    /// <para>
    /// The watch only knows about playback since it was made. Quiet time counts from then, not "forever", so right
    /// after Jellyfin starts nothing reads as quiet until the time asked has passed (Trailhead, #31).
    /// </para>
    /// <para>
    /// Each plugin makes its own watch with <see cref="For"/> at start and disposes it on stop. It holds no state in
    /// the registry, so an in-process restart (#33) simply starts a new one.
    /// </para>
    /// <para>
    /// A plugin that sees playback Jellyfin doesn't report as a session (CleanStream: open stream and download
    /// requests from apps that send no progress) publishes it as an activity with the user, and it holds quiet like
    /// any other. That needs no extra hook, and it fails open when that plugin isn't installed.
    /// </para>
    /// </summary>
    internal sealed class QuietWatch : IDisposable
    {
        private readonly Func<IEnumerable<PlayingSession>> _sessions;
        private readonly Func<DateTime> _clock;
        private readonly Action? _unsubscribe;
        private readonly IDisposable? _activityEnded;
        private long _lastPlaybackTicks;

        /// <summary>For tests and adapters: the playing sessions and the clock as plain functions.</summary>
        internal QuietWatch(Func<IEnumerable<PlayingSession>> sessions, Func<DateTime>? clock = null)
            : this(sessions, clock, null)
        {
        }

        private QuietWatch(Func<IEnumerable<PlayingSession>> sessions, Func<DateTime>? clock, Action? unsubscribe)
        {
            _sessions = sessions;
            _clock = clock ?? (() => DateTime.UtcNow);
            _unsubscribe = unsubscribe;
            _lastPlaybackTicks = _clock().Ticks;

            // A holder that ends between two checks still restarts the clock (GameTent, #51). Only activities with a
            // user: an ended download or rebuild with nobody behind it never held quiet.
            try
            {
                _activityEnded = CampgroundEvents.Subscribe(EventNames.ActivityEnded, e =>
                {
                    if (e.ValueKind == JsonValueKind.Object && HasUser(e))
                    {
                        NotePlayback();
                    }
                });
            }
            catch (Exception)
            {
                _activityEnded = null;
            }
        }

        /// <summary>
        /// A watch on Jellyfin's sessions. It listens to playback start, progress and stop until disposed.
        /// </summary>
        internal static QuietWatch For(ISessionManager sessionManager)
        {
            QuietWatch? watch = null;
            EventHandler<PlaybackProgressEventArgs> onPlayback = (_, _) => watch?.NotePlayback();
            EventHandler<PlaybackStopEventArgs> onStop = (_, _) => watch?.NotePlayback();

            watch = new QuietWatch(
                () => Playing(sessionManager),
                null,
                () =>
                {
                    sessionManager.PlaybackStart -= onPlayback;
                    sessionManager.PlaybackProgress -= onPlayback;
                    sessionManager.PlaybackStopped -= onStop;
                });

            sessionManager.PlaybackStart += onPlayback;
            sessionManager.PlaybackProgress += onPlayback;
            sessionManager.PlaybackStopped += onStop;
            return watch;
        }

        /// <summary>Records that playback was seen now. <see cref="For"/> calls it from Jellyfin's playback events.</summary>
        internal void NotePlayback()
        {
            var now = _clock().Ticks;
            long seen;
            do
            {
                seen = Interlocked.Read(ref _lastPlaybackTicks);
                if (now <= seen)
                {
                    return;
                }
            }
            while (Interlocked.CompareExchange(ref _lastPlaybackTicks, now, seen) != seen);
        }

        /// <summary>
        /// Whether the server has been quiet for at least <paramref name="quietFor"/>, and what is holding it if not.
        /// </summary>
        /// <param name="quietFor">Trailhead passes 60 s, FieldGuide 10 minutes.</param>
        /// <param name="activityKinds">Activity kinds that hold quiet even with no user. Activities with a user
        /// always hold it.</param>
        internal QuietState Check(TimeSpan quietFor, IReadOnlyCollection<string>? activityKinds = null)
        {
            var holding = new List<string>();

            // A failure to read the sessions isn't quiet: the caller is about to restart Jellyfin or start heavy work.
            try
            {
                foreach (var s in _sessions())
                {
                    holding.Add(Describe(s));
                }
            }
            catch (Exception)
            {
                holding.Add("Jellyfin's sessions couldn't be read");
            }

            foreach (var a in Sessions.ListActivities())
            {
                if (a.UserId != null || (activityKinds != null && activityKinds.Contains(a.Kind, StringComparer.Ordinal)))
                {
                    holding.Add($"{a.PluginId}: {(string.IsNullOrWhiteSpace(a.Title) ? a.Kind : a.Title)}");
                }
            }

            foreach (var lease in EncoderLedger.Snapshot())
            {
                holding.Add($"{lease.PluginId}: encoder in use ({lease.Purpose})");
            }

            if (holding.Count > 0)
            {
                // Quiet counts from the last check that saw a holder too, not only from Jellyfin playback: a game that
                // ends and is relaunched seconds later must not read as quiet in between (GameTent, #51).
                NotePlayback();
                return new QuietState(false, TimeSpan.Zero, holding);
            }

            var quietTicks = _clock().Ticks - Interlocked.Read(ref _lastPlaybackTicks);
            var quietSpan = quietTicks > 0 ? TimeSpan.FromTicks(quietTicks) : TimeSpan.Zero;
            var quiet = quietFor <= TimeSpan.Zero || (quietTicks > 0 && quietSpan >= quietFor);
            return new QuietState(quiet, quietSpan, holding);
        }

        /// <summary>Stops listening to Jellyfin's playback events.</summary>
        public void Dispose()
        {
            _unsubscribe?.Invoke();
            _activityEnded?.Dispose();
        }

        private static bool HasUser(JsonElement activity)
        {
            foreach (var p in activity.EnumerateObject())
            {
                if (string.Equals(p.Name, "UserId", StringComparison.OrdinalIgnoreCase))
                {
                    return p.Value.ValueKind == JsonValueKind.String && !string.IsNullOrWhiteSpace(p.Value.GetString());
                }
            }

            return false;
        }

        private static string Describe(PlayingSession s)
        {
            var who = string.IsNullOrWhiteSpace(s.UserName) ? "Someone" : s.UserName;
            var verb = s.Paused ? "has paused" : "is playing";
            return string.IsNullOrWhiteSpace(s.DeviceName) ? $"{who} {verb}" : $"{who} {verb} on {s.DeviceName}";
        }

        private static IEnumerable<PlayingSession> Playing(ISessionManager sessionManager)
            => sessionManager.Sessions
                .Where(s => s.NowPlayingItem != null)
                .Select(s => new PlayingSession(s.UserName, s.DeviceName, s.PlayState?.IsPaused ?? false))
                .ToList();
    }
}
